// Generated from the Premium Library sources: the opening pages of each book,
// shown as a free sample on its store page.

export type ExcerptBlock = ["p" | "h" | "li" | "q", string];
export type Excerpt = { chapter: string; blocks: ExcerptBlock[] };

export const EXCERPTS: Record<string, Excerpt> = {
  "01-foundations-of-strength": {"chapter": "Why Strength Comes First", "blocks": [["p", "Walk into any gym in January and you will see two kinds of beginners. The first heads straight for the treadmill, stays there for forty minutes, leaves sweaty and tired, and is gone by March. The second spends the first few weeks learning to squat, push, pull and carry — slowly, with light weights and a lot of attention — and is still training a year later, visibly changed."], ["p", "The difference is rarely willpower. It is that the second person started with the one quality that improves almost everything else: strength."], ["h", "What strength actually is"], ["p", "Strength is your ability to produce force — to push, pull, lift, carry and resist. It is not the same as size, and it is not the same as fitness in the breathless, cardio sense. A strong person can get off the floor without using their hands, carry a 20-litre water can up the stairs, pick up a child without their back complaining, and still feel capable at seventy."], ["p", "Strength is also trainable at any age. Studies in people in their eighties and nineties have shown clear strength gains from simple resistance training in a matter of weeks. Whatever age you are reading this at, your muscles will respond."]]},
  "02-hypertrophy-decoded": {"chapter": "How Muscle Grows", "blocks": [["p", "Muscle hypertrophy — the growth of muscle fibres — is the body's response to a demand it can't comfortably meet. When muscles repeatedly work against challenging resistance, they adapt by becoming larger and able to produce more force. Understanding how this happens makes every training decision clearer."], ["h", "The muscle fibre"], ["p", "A skeletal muscle is made of thousands of long cells called fibres, bundled together. Each fibre contains contractile proteins (mainly actin and myosin) arranged in repeating units that slide past each other to produce force. When a fibre grows, it mainly adds more of these contractile proteins, becoming thicker."], ["h", "Mechanical tension: the primary driver"], ["p", "The most important stimulus for growth is mechanical tension — the force muscle fibres experience when they contract against a load, particularly when they contract hard and slowly enough to generate high force. Specialised sensors in the muscle detect this tension and switch on signalling pathways that increase muscle protein synthesis."], ["p", "This explains several practical facts:"], ["li", "Heavy and moderate loads both work — what matters is that the fibres experience high tension, which happens near the end of a challenging set, even with lighter weights."], ["li", "Effort matters — the last few reps of a hard set recruit the largest, most growth-prone motor units."], ["li", "Control matters — throwing weights around shifts tension away from the target muscle."]]},
  "03-fat-loss-blueprint": {"chapter": "What Fat Loss Really Is", "blocks": [["p", "Body fat is stored energy. When you take in less energy from food than your body uses, it draws on stored energy — including fat — to make up the difference. That is the foundation of every successful fat-loss approach, whatever it's called."], ["p", "But \"eat less, move more\" is a slogan, not a plan. Your body adapts to dieting: hunger rises, energy dips, daily movement often drops without you noticing, and if you don't train and eat enough protein, some of the weight you lose is muscle. A good plan accounts for all of this."], ["h", "Weight loss versus fat loss"], ["p", "The scale measures everything: fat, muscle, water, food in your gut, and glycogen (stored carbohydrate, which holds water). Early drops on a new diet are often mostly water and glycogen. Day-to-day changes are mostly water. What you want is fat loss while keeping muscle — which may show on the scale more slowly but changes how you look and feel far more."]]},
  "04-powerlifting-fundamentals": {"chapter": "What Powerlifting Is", "blocks": [["p", "Powerlifting tests maximal strength in three lifts: the squat, bench press and deadlift. In competition, each lifter gets three attempts at each lift. The best successful attempt in each lift is added together to make a total. Lifters compete in weight classes, age categories and divisions, and placings can also be compared across body weights using formulas."], ["h", "Equipped and raw (classic)"], ["li", "Raw/classic lifting allows a belt, knee sleeves, wrist wraps and appropriate shoes. This is the most popular division for new lifters."], ["li", "Equipped lifting allows supportive suits and shirts that store elastic energy and allow heavier weights. It requires specialised technique."], ["p", "This book focuses on raw/classic powerlifting."], ["h", "Federations"], ["p", "Powerlifting has several federations with slightly different rules. Internationally, the International Powerlifting Federation (IPF) is the largest drug-tested federation; India has national bodies affiliated to international federations, and state and district associations run local meets. Always read the current rulebook of the federation you're entering, and check its anti-doping rules."]]},
  "05-home-strength-manual": {"chapter": "Why Home Training Works", "blocks": [["p", "Home workouts have a reputation problem. Many people try them, do the same twenty minutes of jumping jacks and crunches for a few weeks, see little change, and conclude home training \"doesn't work\". The problem isn't the location. It's the lack of progressive overload."], ["p", "Muscles don't know whether they're in a gym or a living room. They respond to tension, effort and progression. With the right exercises and a way to keep increasing difficulty, home training can build significant strength and muscle — especially in the first one to two years."], ["h", "Advantages of training at home"], ["li", "No commute — the single biggest barrier to consistency for many people."], ["li", "No waiting for equipment."], ["li", "Privacy for beginners who feel self-conscious."], ["li", "Flexibility — train at 5 AM or 11 PM."], ["li", "Low cost once set up."], ["h", "Limitations to plan around"], ["li", "Lower-body loading is harder without heavy weights; unilateral exercises and tempo solve much of this."], ["li", "Pulling exercises need some equipment: a pull-up bar, bands, or a sturdy table for rows."], ["li", "Distractions — family, phone, TV. A fixed time and a dedicated space help."], ["q", "The best gym is the one you use. If home is where you'll train consistently, home is the best gym for you."]]},
  "06-strong-women": {"chapter": "Why Strength Matters for Women", "blocks": [["p", "Strength training changes how you look — but its real value runs deeper. It's about carrying children and groceries without strain, protecting your bones and joints as you age, managing your metabolic health, and moving through life with confidence."], ["h", "Benefits that matter at every age"], ["li", "Muscle and metabolism: muscle supports blood sugar control and helps maintain a healthy body composition."], ["li", "Bone density: resistance training is one of the most effective ways to maintain and build bone — crucial because women face a higher risk of osteoporosis, particularly after menopause."], ["li", "Joint health and posture: stronger muscles support the knees, hips, back and shoulders."], ["li", "Mental health: regular strength training is associated with improved mood, reduced anxiety and greater self-esteem."], ["li", "Independence later in life: strength is strongly linked with the ability to live independently as we age."], ["h", "The Indian context"], ["p", "Many Indian women juggle work, household responsibilities and caregiving, often with little time for themselves. Rates of vitamin D deficiency, anaemia and low bone density are common, and South Asian women face elevated risks of type 2 diabetes and heart disease. Strength training two or three times a week is a practical, high-return investment in long-term health."]]},
  "07-strong-after-forty": {"chapter": "The Case for Lifting After Forty", "blocks": [["p", "From around our thirties and forties, muscle mass and strength decline gradually if we don't train them — a process called sarcopenia when it becomes significant. Power (the ability to produce force quickly) declines even faster. Bone density follows a similar path, especially in women after menopause. Left unchecked, these changes lead to slower walking, difficulty climbing stairs, falls, fractures and loss of independence."], ["p", "The encouraging part: all of these respond to training at any age. Studies in older adults, including people in their eighties and nineties, have shown meaningful gains in strength and function from progressive resistance training."], ["h", "What strength training offers after forty"], ["q", "Muscle is like a retirement fund: the more you build and protect before you need it, the more comfortably you'll live later."], ["h", "Before You Start"], ["h", "See your doctor if you:"], ["li", "Have heart disease, high blood pressure, diabetes, kidney disease or another chronic condition."], ["li", "Have chest pain, breathlessness or dizziness on exertion."], ["li", "Have osteoporosis, a history of fractures, or joint replacements."], ["li", "Take medicines that affect heart rate, blood pressure or blood sugar."], ["li", "Have been inactive for a long time and plan to begin vigorous exercise."]]},
  "08-mobility-injury-prevention": {"chapter": "Mobility, Flexibility and Stability", "blocks": [["p", "People use \"mobility\" and \"flexibility\" interchangeably, but they're different, and the difference matters for lifters."], ["li", "Flexibility is how far a joint can be moved passively — for example, how far someone can push your leg up while you lie relaxed."], ["li", "Mobility is how far you can actively control a joint through its range — moving there yourself, with strength."], ["li", "Stability is the ability to control position and resist unwanted movement, especially under load."], ["p", "A lifter can be very flexible yet unable to control the bottom of a deep squat. Another can be strong but too stiff to reach good positions. The goal is usable range: enough mobility to reach the positions your training demands, and the strength and control to own them under load."], ["h", "Why this matters"], ["p", "When you can't reach a position, your body finds a way around it — a \"compensation\". If your ankles are stiff, your heels may lift or your back may round in a squat. Compensations aren't always harmful, but under heavy, repeated load they can concentrate stress in places that don't tolerate it well."], ["q", "You don't need the flexibility of a gymnast. You need enough controlled range for the exercises you do, plus a little to spare."]]},
  "09-conditioning-without-burnout": {"chapter": "Why Lifters Need Conditioning", "blocks": [["p", "Strength training builds the chassis; conditioning builds the engine. A lifter with poor aerobic fitness gets breathless walking up stairs, recovers slowly between heavy sets, and carries a higher long-term risk of heart disease, stroke and diabetes. Cardiorespiratory fitness is one of the strongest predictors of long-term health in the research literature — people with higher fitness levels tend to live longer, healthier lives."], ["h", "What conditioning gives a lifter"], ["h", "The burnout trap"], ["p", "Many people approach cardio with all-out intensity every time: gasping HIIT classes five days a week on top of heavy lifting. That combination often leads to exhaustion, stalled strength, poor sleep and dropping out. The solution isn't less conditioning — it's smarter conditioning, built mostly on easy work with small amounts of hard effort."], ["q", "Most of your conditioning should feel easy. The fittest endurance athletes in the world do the large majority of their training at low intensity — and they're anything but unfit."]]},
  "10-calisthenics-mastery": {"chapter": "The Calisthenics Philosophy", "blocks": [["p", "Calisthenics comes from the Greek words for beauty (kalos) and strength (sthenos). It's training with your own body as the resistance: push-ups, pull-ups, dips, squats, handstands, and the gymnastic skills built on them."], ["h", "Why calisthenics"], ["li", "Accessible: a floor, a bar, parallel bars or a park — and you're set."], ["li", "Relative strength: you get strong for your body weight, which carries over to sport and daily life."], ["li", "Body control: balance, coordination and core strength develop alongside muscle."], ["li", "Skill progression: clear milestones — your first pull-up, a pistol squat, a handstand, a muscle-up — keep training motivating for years."], ["li", "Joint health: done progressively, it builds resilient shoulders, elbows and wrists."], ["h", "The challenge"], ["p", "Calisthenics is harder to progress than weight training, because you can't add 2.5 kg. Instead, you progress by changing leverage, range of motion, number of limbs, tempo and eventually added weight. This book organises every skill into progressions — steps from easier to harder — so you always know your next goal."], ["q", "In calisthenics, patience is a skill. Tendons and joints adapt more slowly than muscles, and the lifters who rush advanced skills are the ones who end up with sore elbows and wrists."]]},
  "11-athletes-recovery-handbook": {"chapter": "Why Recovery Is Training", "blocks": [["p", "Every training session is a stress. It depletes energy stores, creates small amounts of muscle damage, fatigues the nervous system and triggers hormonal and inflammatory responses. In the hours and days afterwards, the body repairs and adapts — becoming slightly stronger, fitter and more resilient. That adaptation is the whole point of training, and it happens during recovery."], ["h", "Fitness and fatigue"], ["p", "A useful model separates the effects of training into two components:"], ["li", "Fitness: the positive adaptation — more strength, muscle and endurance — which builds slowly and lasts."], ["li", "Fatigue: the temporary negative effect — tiredness, soreness, reduced performance — which builds quickly and fades."], ["p", "Your performance on any given day is roughly fitness minus fatigue. Hard training raises both; recovery removes fatigue so the fitness can show. This is why people often perform their best after a lighter week."], ["q", "You don't get stronger from training. You get stronger from recovering from training."]]},
  "12-programme-design-for-coaches": {"chapter": "The Coach's Job", "blocks": [["p", "A training programme is a set of instructions designed to produce a specific adaptation in a specific person. The best programme on paper fails if the client can't or won't follow it. That's why programme design is as much about people as physiology."], ["h", "What great programmes have in common"], ["li", "A clear goal that the client cares about."], ["li", "Appropriate exercise selection for the client's body, experience and equipment."], ["li", "The right dose — enough stimulus to drive adaptation, not so much that recovery fails."], ["li", "Progression — a plan for doing a little more over time."], ["li", "Flexibility — ways to adjust when life happens."], ["li", "Adherence — the client actually enjoys enough of it to keep coming back."], ["q", "The best programme is the one the client completes. A good plan done consistently beats a perfect plan done occasionally."], ["h", "The coaching cycle"], ["h", "The Client Assessment"], ["h", "Health screening"], ["p", "Before training anyone, screen for conditions that require medical clearance. A pre-exercise questionnaire should ask about:"], ["li", "Heart disease, chest pain, fainting or palpitations."], ["li", "High blood pressure, diabetes, kidney or lung disease."], ["li", "Pregnancy or recent childbirth."], ["li", "Recent surgery, injuries, joint replacements."], ["li", "Medications."], ["li", "Family history of sudden cardiac death at a young age."], ["p", "Refer clients with red flags to a doctor before starting or progressing to vigorous training."]]},
  "13-the-indian-plate": {"chapter": "Why Indian Food Works for Fitness", "blocks": [["p", "Indian cuisine is one of the most diverse and nutritious in the world. A traditional thali — dal, a vegetable, roti or rice, curd, salad and a little pickle — covers most nutritional bases. Spices like turmeric, cumin, ginger and garlic add flavour without calories. Legumes, whole grains, vegetables and fermented dairy are everyday staples."], ["p", "So why do so many Indians struggle with weight, blood sugar and low muscle mass? Modern Indian eating has drifted from the traditional thali in a few predictable ways:"], ["p", "Fix these gaps and Indian food becomes an outstanding fitness diet."], ["q", "The goal isn't to replace Indian food. It's to rebalance the plate: more protein and vegetables, measured oil, smarter carbohydrates, less sugar."], ["h", "The Macronutrients"], ["h", "Protein"], ["p", "Builds and repairs muscle and other tissues; keeps you full. Indian sources: dal, rajma, chole, soya, paneer, curd, milk, tofu, eggs, chicken, fish, mutton."], ["p", "Target for active people: about 1.4–2.0 g per kg body weight per day."]]},
  "14-protein-without-confusion": {"chapter": "What Protein Does", "blocks": [["p", "Protein is made of amino acids — the building blocks of muscles, enzymes, hormones, antibodies, skin, hair and much more. Your body constantly breaks down and rebuilds proteins; dietary protein supplies the amino acids to do it."], ["h", "Essential amino acids"], ["p", "There are 20 amino acids in human proteins. Nine are essential: the body can't make them, so they must come from food. One essential amino acid, leucine, plays a special role in triggering muscle protein synthesis."], ["h", "Protein's roles in fitness"], ["q", "Training creates the signal for muscle growth; protein supplies the materials. Without enough protein, the signal is wasted."], ["h", "How Much Do You Need?"], ["p", "The general recommended dietary allowance for adults (around 0.8 g per kg body weight per day) is set to prevent deficiency in most people — not to optimise muscle building or support intense training."], ["h", "Practical targets"], ["p", "Research on muscle gain in resistance-trained people suggests benefits largely level off around 1.6 g/kg, with some people benefiting up to about 2.2 g/kg. Higher intakes during fat loss help protect muscle."]]},
  "15-supplements-evidence-vs-hype": {"chapter": "The Supplement Market", "blocks": [["p", "Supplements are big business in India, sold through gyms, pharmacies, e-commerce platforms and social media. Unlike prescription medicines, most supplements don't need to prove effectiveness before sale. Marketing often relies on testimonials, influencer endorsements, cherry-picked studies, and before-and-after photos that owe more to training, diet, lighting — or drugs — than to the product."], ["h", "Three problems with supplements"], ["li", "Many don't work as advertised."], ["li", "Some contain what they shouldn't: undeclared drugs, stimulants or contaminants."], ["li", "Some are counterfeit: fake versions of popular brands are sold online and in shops."], ["h", "What supplements can and can't do"], ["p", "Supplements can fill specific gaps (like vitamin D deficiency) or provide small performance edges (like creatine). They can't replace consistent training, adequate food, sleep and recovery — which together account for the vast majority of results."], ["q", "If your training, diet and sleep aren't in order, supplements are a rounding error. If they are in order, a few supplements can add a small, real benefit."]]},
  "16-eating-for-hormonal-health": {"chapter": "Hormones in Plain Language", "blocks": [["p", "Hormones are chemical messengers released by glands into the bloodstream, carrying signals to organs and tissues. They control metabolism, growth, reproduction, mood, sleep, appetite and how the body stores and uses energy."], ["h", "The hormones in this book"], ["h", "What food can and can't do"], ["p", "Food, exercise, sleep and stress management can strongly influence insulin sensitivity, body weight and some hormonal symptoms. They can't cure an underactive thyroid, replace medication for diabetes when it's needed, or \"balance hormones\" in the vague way marketing promises."], ["q", "Be wary of anyone who sells \"hormone-balancing\" teas, detoxes or diets. Real hormonal conditions need real diagnosis — and the best lifestyle strategies are usually simple."], ["h", "Insulin and Blood Sugar"], ["p", "After a meal, carbohydrates are digested into glucose, which enters the bloodstream. Insulin helps move glucose into muscle, liver and fat cells. When cells respond poorly to insulin — insulin resistance — the pancreas must produce more, and blood sugar may gradually rise."]]},
  "17-the-lean-bulk": {"chapter": "What a Lean Bulk Is", "blocks": [["p", "A \"bulk\" is a period of deliberately eating more energy than you burn to support muscle growth. A lean bulk keeps the surplus small and controlled, so that a high proportion of the weight gained is muscle rather than fat."], ["h", "Why not just eat everything?"], ["p", "Old-school \"dirty bulking\" — eating huge amounts of anything — does produce weight gain. But muscle can only grow so fast. Beyond a modest surplus, extra energy mostly becomes fat. The result: a long, unpleasant diet afterwards, and often more fat than muscle gained."], ["h", "Why not stay at maintenance?"], ["p", "Beginners and people returning to training can build muscle at maintenance or even in a small deficit (\"recomposition\"). But for most people past the first year of training, a modest surplus produces faster, more reliable muscle gain."], ["q", "Muscle grows slowly. Your surplus should match that pace — not your appetite."], ["h", "Who Should Bulk"], ["h", "Good candidates"], ["li", "Lean to moderately lean individuals who want more muscle."], ["li", "\"Hardgainers\" who struggle to gain any weight."], ["li", "Lifters who have trained consistently and want to keep progressing."]]},
  "18-meal-prep": {"chapter": "Why Meal Prep Works", "blocks": [["p", "Willpower is weakest when you are tired and hungry. Meal prep moves food decisions to a moment when you're calm, rested and thinking clearly — usually a weekend morning."], ["h", "What meal prep does for you"], ["li", "Removes daily decisions. Lunch is already in a box."], ["li", "Controls portions. You portion once rather than guessing at every meal."], ["li", "Saves money. Cooking in bulk is cheaper than ordering in."], ["li", "Saves time. Two hours on Sunday replaces 30–60 minutes every weekday."], ["li", "Protects your goals. Protein targets are easy to hit when the protein is already cooked."], ["q", "You don't rise to the level of your goals; you fall to the level of what's in your fridge."], ["h", "What meal prep isn't"], ["p", "It isn't eating bland chicken and broccoli from plastic boxes seven days a week. Good meal prep means preparing components — proteins, grains, vegetables, sauces — and combining them differently through the week."], ["h", "The Component Method"], ["p", "Instead of cooking seven identical meals, prepare four to six components and assemble varied meals from them."]]},
  "19-yoga-for-absolute-beginners": {"chapter": "What Yoga Is — and Isn't", "blocks": [["p", "The word yoga comes from the Sanskrit root yuj, often translated as \"to join\" or \"to yoke\". For thousands of years in India, yoga was a broad discipline of ethics, self-study, breath, concentration and meditation, of which physical postures were only one part. The modern image of yoga — flexible people in elaborate poses — captures just a sliver of it."], ["p", "This book focuses on the parts that most beginners start with: asana (postures), pranayama (breath), and relaxation and meditation. Practised regularly, these three improve flexibility, strength, balance, posture and breathing, and many people find they help with stress and sleep."], ["h", "What yoga isn't"], ["li", "It isn't a flexibility contest. Flexibility is a result of practice, not a requirement for it."], ["li", "It isn't only for the young, slim or supple. Yoga can be adapted for almost any body, age and fitness level."], ["li", "It isn't a religion you must adopt. Yoga grew from Indian philosophical traditions, and many practitioners find meaning in that; others practise purely for health. Both are welcome."], ["li", "It isn't a cure for disease. Yoga can support wellbeing alongside medical care, but it doesn't replace it."]]},
  "20-sun-salutation": {"chapter": "What Is Surya Namaskar?", "blocks": [["p", "Surya Namaskar — \"salutation to the sun\" — is a flowing sequence of postures linked with the breath. Traditionally practised at sunrise, facing east, it is one of the best-known practices in yoga."], ["h", "Why it's so popular"], ["li", "Complete: it moves the spine forwards and backwards and works the arms, shoulders, core, hips and legs."], ["li", "Efficient: a few rounds take only a few minutes."], ["li", "Adaptable: it can be slow and meditative or fast and vigorous."], ["li", "Needs no equipment: a mat and a small space are enough."], ["h", "A short history"], ["p", "Sun worship has ancient roots in India, including Vedic hymns to Surya. The flowing physical sequence we practise today became widely popular in the 20th century, notably promoted by the Raja of Aundh and later taught by many yoga schools. Today there are several versions — the classical 12-step sequence, Ashtanga's Surya Namaskar A and B, and others."], ["q", "There's no single \"correct\" version. What matters is moving with the breath, with attention, and within your capacity."]]},
  "21-yoga-back-pain": {"chapter": "The Desk Body", "blocks": [["p", "Long hours of sitting are a modern reality. Many people blame \"bad posture\" for every ache. The truth is more nuanced — and more hopeful."], ["h", "What we know"], ["li", "Back pain is extremely common. Most adults experience it at some point; most episodes improve within weeks."], ["li", "No single \"perfect posture\" exists. The best posture is your next posture — changing position regularly matters more than holding any one position."], ["li", "Movement helps. Staying active is generally better for common back pain than bed rest."], ["li", "Exercise, including yoga, has evidence for reducing chronic low back pain and improving function, with modest effects similar to other forms of exercise therapy."], ["h", "What prolonged sitting does contribute to"], ["li", "Stiffness in the hips, upper back and neck."], ["li", "Reduced activity overall, which affects heart health and weight."], ["li", "Fatigue and discomfort from staying static."], ["q", "Your back isn't fragile. It's built to move — and it often hurts because it's moved too little, not too much."]]},
  "22-yoga-for-lifters": {"chapter": "Why Lifters Need Yoga", "blocks": [["h", "The objections"], ["li", "\"Stretching makes you weak.\""], ["li", "\"Yoga is for flexibility; I need strength.\""], ["li", "\"I don't have time.\""], ["h", "The reality"], ["li", "Moderate evidence: Long static stretching immediately before maximal lifting may slightly reduce force output for some people — but dynamic mobility in a warm-up does not, and stretching at other times doesn't make you weaker."], ["li", "Many lifts demand positions: deep hip flexion for squats, shoulder flexion for overhead pressing, thoracic extension for bench arch and front squats."], ["li", "Yoga offers active mobility (strength at end range), recovery (low-intensity movement and relaxation) and breath control (useful for bracing and calming nerves)."], ["q", "Mobility without strength is a party trick. Strength without mobility limits what you can express. Lifters need both."], ["h", "Mobility vs Flexibility"], ["p", "Yoga poses can train all three: held postures build strength at end range, and flowing sequences build control through the range."], ["h", "Assessing Yourself"], ["p", "Test each and note the result."], ["q", "Tests I passed easily: ___ x1 Tests that were limited: ___ x1 Lifts affected by these limitations: ___ x1"]]},
  "23-pranayama": {"chapter": "What Is Pranayama?", "blocks": [["p", "The Sanskrit word pranayama is often translated as \"extension (ayama) of the vital energy (prana)\", or \"control of the breath\". In Patanjali's Yoga Sutras, it is the fourth of the eight limbs of yoga, following posture (asana) and preceding the withdrawal of the senses (pratyahara)."], ["h", "Traditional view"], ["p", "Classical texts such as the Hatha Yoga Pradipika describe pranayama as a way to purify the energy channels (nadis), steady the mind and prepare for meditation."], ["h", "Modern view"], ["p", "Scientists study breathing practices through physiology: how breathing rate, depth and the ratio of inhalation to exhalation influence the nervous system, heart rate variability, blood gases and attention."], ["q", "Breathing is one of the few bodily functions that runs automatically yet can also be controlled consciously. That makes it a bridge between body and mind."], ["h", "The Physiology of Breath"], ["h", "The mechanics"], ["p", "The diaphragm — a dome-shaped muscle beneath your lungs — is the main breathing muscle. As it contracts and moves down, the lungs expand and air flows in. Accessory muscles in the neck and chest help during heavy breathing or stress."]]},
  "24-restorative-yin": {"chapter": "Slow Yoga", "blocks": [["p", "In a world that rewards speed and intensity, slowing down can feel unproductive. Yet rest and recovery are when the body adapts and the mind settles."], ["h", "Two slow styles"], ["q", "Restorative yoga asks, \"How comfortable can I be?\" Yin asks, \"Can I stay with mild discomfort, calmly?\""], ["h", "Why It Helps"], ["h", "Possible benefits"], ["li", "Stress reduction: long, supported poses with slow breathing can shift the nervous system toward rest."], ["li", "Sleep: gentle evening practice may help you wind down."], ["li", "Recovery: a low-intensity complement to hard training."], ["li", "Flexibility: Yin's longer holds may improve range of motion over time."], ["li", "Mindfulness: stillness gives practice in observing sensations and thoughts."], ["p", "Moderate evidence: Research specifically on restorative and Yin yoga is limited, but studies on gentle yoga and relaxation practices show improvements in perceived stress, sleep quality and wellbeing for many participants."], ["h", "What the science on \"fascia\" can and can't say"], ["p", "Yin is often described as targeting fascia and connective tissue. Connective tissue does respond to loading over time, but specific claims — such as \"rehydrating fascia\" or \"releasing stored emotions\" — go beyond current evidence. The practice can be valuable without those claims."]]},
  "25-yoga-womens-health": {"chapter": "Practising Through Life's Stages", "blocks": [["p", "Women's health is often discussed only in terms of reproduction. In reality, hormones, bones, muscles, pelvic floor, mood and energy change throughout life — and yoga can be adapted for every stage."], ["q", "Yoga is not a treatment for gynaecological conditions. It is a supportive practice that can help with pain, stress, mobility, strength and wellbeing — alongside proper medical care."], ["h", "Understanding the Menstrual Cycle"], ["p", "A typical cycle lasts about 21–35 days and has four phases."], ["p", "Important: individual experiences vary widely. Moderate evidence: The research on adjusting training to cycle phases is mixed. Listening to your own body is more useful than following rigid phase-based rules."], ["h", "Tracking your cycle"], ["p", "Note your period dates, energy, mood, sleep and symptoms for 2–3 months. Patterns often emerge that help you plan your practice."], ["h", "Practising During Menstruation"], ["p", "There's no universal rule. Some women feel great and practise normally; others need rest."], ["h", "Gentle options"], ["li", "Supported child's pose, reclined bound angle, supported forward folds."], ["li", "Cat–cow and gentle pelvic tilts."], ["li", "Slow walking."], ["li", "Restorative practice (Vol. 24)."]]},
  "26-yoga-sutras": {"chapter": "Who Was Patanjali?", "blocks": [["p", "The Yoga Sutras are attributed to Patanjali, about whom very little is known for certain. Scholars generally date the text to somewhere between the 2nd century BCE and the 5th century CE, with many placing it around the early centuries CE."], ["h", "The form"], ["p", "A sutra is a \"thread\" — a short, condensed statement designed to be memorised and explained by a teacher. The Sutras are so compressed that they've generated many commentaries, beginning with the one attributed to Vyasa."], ["h", "The four chapters (padas)"], ["p", "(Numbering varies slightly across editions.)"], ["q", "Notice what's barely mentioned: postures. Of nearly 200 sutras, only a handful discuss asana. Classical yoga is primarily about the mind."], ["h", "Yoga Is the Stilling of the Mind"], ["p", "The most famous line in the text:"], ["q", "Yogash chitta vritti nirodhah — \"Yoga is the stilling of the fluctuations of the mind.\""], ["h", "Key terms"], ["li", "Chitta: the mind-field, or consciousness."], ["li", "Vritti: fluctuations, movements, whirlpools."], ["li", "Nirodha: stilling, restraint, cessation."], ["h", "The five types of vritti (1.5–1.11)"], ["h", "Why it matters today"], ["p", "Our minds are bombarded with notifications, comparisons and noise. The Sutras' central insight — that peace comes from steadying the mind rather than controlling the world — is strikingly relevant."]]},
  "27-meditation-made-simple": {"chapter": "Why Meditate", "blocks": [["p", "Imagine trying to read a book on a bus while three people talk to you at once, your phone buzzes, and you're also worrying about tomorrow's meeting. That is how many of us live most of the day: attention pulled in every direction, rarely resting anywhere."], ["p", "Meditation is training for attention. It is the deliberate practice of placing your attention somewhere — the breath, the body, sounds — noticing when it wanders, and bringing it back. Over time, this simple practice changes how you relate to your own mind."], ["h", "What people commonly notice"], ["p", "People who practise regularly often report:"], ["li", "Feeling calmer and less reactive to stress."], ["li", "Better focus and less mental \"scatter\"."], ["li", "Improved sleep, particularly falling asleep."], ["li", "More awareness of emotions before they take over."], ["li", "Greater patience with themselves and others."], ["p", "Research on mindfulness-based programmes has found benefits for stress and some measures of anxiety and low mood, and structured programmes are used in healthcare in several countries. Effects vary between people, studies differ in quality, and meditation isn't a cure-all — but for many people, a small daily practice makes a real difference."]]},
  "28-breathwork-performance": {"chapter": "The Breath as a Lever", "blocks": [["p", "Your heart rate, muscle tension, alertness and emotional state are tightly linked to the way you breathe."], ["h", "Two directions"], ["h", "Why the exhale calms"], ["p", "During inhalation, heart rate rises slightly; during exhalation, it falls (respiratory sinus arrhythmia). Emphasising the exhale biases the system toward calm."], ["q", "You can't simply \"decide\" to stop being anxious. But you can decide to exhale slowly — and the body follows."], ["h", "The Science in Brief"], ["li", "Oxygen: at rest, healthy people's blood is already about 95–99% saturated. Breathing harder rarely increases oxygen delivery meaningfully."], ["li", "Carbon dioxide: CO₂ levels drive the urge to breathe. Over-breathing lowers CO₂, which can cause dizziness, tingling and a feeling of anxiety."], ["li", "The Bohr effect: CO₂ helps release oxygen from haemoglobin to tissues. Chronic over-breathing may, in theory, reduce oxygen delivery efficiency."], ["li", "Heart rate variability (HRV): higher HRV at rest is generally associated with better recovery and resilience. Slow breathing can increase HRV acutely."]]},
  "29-yoga-nidra": {"chapter": "What Is Yoga Nidra?", "blocks": [["p", "Yoga Nidra is a guided practice, done lying down, that leads you into a state between waking and sleeping, while you keep a thread of awareness."], ["h", "Origins"], ["p", "The modern practice was systematised by Swami Satyananda Saraswati of the Bihar School of Yoga in the 1960s, drawing on tantric practices such as nyasa (placing awareness on parts of the body). Many variations now exist, including Richard Miller's iRest and secular \"non-sleep deep rest\" (NSDR) protocols."], ["h", "How it differs from other practices"], ["q", "Yoga Nidra is often described as \"effortless effort\": you follow instructions without trying to achieve anything."], ["h", "What It May Do"], ["h", "The \"one hour of Yoga Nidra = four hours of sleep\" claim"], ["p", "This popular claim is not supported by evidence. Yoga Nidra is restful and restorative, but it doesn't substitute for sleep."], ["h", "The Stages"], ["p", "Most Yoga Nidra practices follow a similar sequence (based on the Satyananda method)."], ["h", "The Sankalpa"], ["p", "A sankalpa is a short, positive statement of intention, made in the present tense."], ["h", "Guidelines"], ["li", "Short and simple."], ["li", "Positive (what you want, not what you don't)."], ["li", "Present tense, as if already true."], ["li", "Meaningful to you."]]},
  "30-mindfulness-anxiety": {"chapter": "Understanding Anxiety", "blocks": [["p", "Anxiety is a normal human emotion — the body's alarm system, designed to protect us from danger. It becomes a problem when the alarm goes off too often, too loudly, or when there's no real threat."], ["h", "The body's alarm"], ["p", "When the brain perceives threat, the sympathetic nervous system activates:"], ["q", "Anxiety symptoms are uncomfortable but not dangerous. Your body is trying to protect you — it's just misjudging the threat."], ["h", "Common anxiety conditions"], ["p", "Only a qualified professional can diagnose these conditions."], ["h", "When to Get Help"], ["q", "Seek urgent help if you have thoughts of harming yourself or ending your life, or if anxiety is so severe you can't function. Call Tele-MANAS on 14416 (free, 24×7, India), 112 for emergencies, or go to the nearest emergency department."], ["h", "See a doctor or mental health professional if"], ["li", "Anxiety interferes with work, study, relationships or daily life."], ["li", "You avoid places or situations because of anxiety."], ["li", "You experience panic attacks."], ["li", "You use alcohol, drugs or other behaviours to cope."], ["li", "Symptoms have lasted several weeks."], ["li", "You also have low mood or depression."]]},
  "31-sleep-reset": {"chapter": "Why Sleep Matters", "blocks": [["q", "You can't out-train, out-diet or out-supplement bad sleep."], ["h", "How much is enough?"], ["p", "Most adults need 7–9 hours. Teenagers need more (8–10). Some people function well on slightly less or more, but very few truly thrive on under 6."], ["h", "How Sleep Works"], ["p", "Sleep is regulated by two main processes:"], ["h", "Process S — sleep pressure"], ["p", "The longer you're awake, the more adenosine builds up in the brain, increasing sleep pressure. Sleep clears it. Caffeine blocks adenosine receptors, masking sleepiness."], ["h", "Process C — the circadian rhythm"], ["p", "Your internal ~24-hour clock, set mainly by light, controls when you feel alert and sleepy. Melatonin rises in the evening as light fades."], ["p", "When sleep pressure is high and your circadian rhythm signals night, you fall asleep easily. Problems arise when these systems are misaligned — late-night screens, irregular schedules, long naps or late caffeine."], ["h", "Sleep stages"], ["p", "A night includes about 4–6 cycles of roughly 90 minutes. Deep sleep dominates early in the night; REM increases towards morning."]]},
  "32-vipassana-insight": {"chapter": "What Is Vipassana?", "blocks": [["p", "Vipassana is a Pali word usually translated as \"insight\" or \"seeing things as they really are\". It refers to meditation practices aimed at direct understanding of the nature of experience."], ["h", "Two wings of meditation"], ["p", "Traditional Buddhist teachings describe two complementary aspects:"], ["p", "Most insight traditions begin with some concentration (often on the breath) and then turn attention to the changing nature of all experience."], ["h", "Is it religious?"], ["p", "Vipassana comes from the Theravada Buddhist tradition, rooted in teachings attributed to the Buddha, particularly the Satipatthana Sutta (the discourse on the foundations of mindfulness). Many modern courses present it as a non-sectarian technique that people of any faith, or none, can practise."], ["q", "Vipassana doesn't ask you to believe anything. It asks you to look — closely and repeatedly — at your own experience."], ["h", "A Brief History"], ["li", "~5th century BCE: the Buddha teaches in northern India. Mindfulness and insight practices are central."], ["li", "Centuries later: Vipassana is preserved mainly in Theravada countries — Myanmar, Thailand and Sri Lanka."], ["li", "19th–20th century Myanmar: a revival of lay meditation. Teachers including Ledi Sayadaw, Mahasi Sayadaw and Sayagyi U Ba Khin develop accessible methods for laypeople."], ["li", "1969: S.N. Goenka, a student of U Ba Khin, begins teaching 10-day courses in India. His organisation's courses are now held at centres worldwide, offered on a donation basis. Dhamma Giri in Igatpuri, Maharashtra, is one of the best-known."], ["li", "1970s onwards: Western teachers bring insight meditation to Europe and the US (for example, Insight Meditation Society). Modern mindfulness programmes such as MBSR draw on these roots."]]},
  "33-focus": {"chapter": "The Attention Crisis", "blocks": [["p", "Attention has become one of the scarcest resources in modern life."], ["h", "The forces against focus"], ["h", "The cost of switching"], ["p", "Each time you switch tasks, your brain needs time to reorient. Research by Gloria Mark and others suggests it can take many minutes to fully return to a complex task after an interruption. Some attention lingers on the previous task (\"attention residue\")."], ["q", "You don't have an attention problem. You have an environment problem, a habit problem — and an untrained attention muscle."], ["h", "How Attention Works"], ["h", "Types of attention"], ["h", "The \"spotlight\" of attention"], ["p", "Attention works like a spotlight: what's in the beam is processed deeply; what's outside fades. Distractions pull the spotlight away."], ["h", "Bottom-up vs top-down"], ["li", "Bottom-up: attention captured by stimuli (a ping, movement, your name)."], ["li", "Top-down: attention directed by your goals."], ["p", "Focus training strengthens top-down control and reduces bottom-up capture."], ["h", "The mind-wandering default"], ["p", "Studies (for example, Killingsworth and Gilbert, 2010) suggest people's minds wander for nearly half their waking hours — and mind-wandering is associated with lower happiness in the moment."]]},
  "34-psychology-of-habit": {"chapter": "Why Change Is Hard", "blocks": [["p", "Think of something you do every day without deciding to: brushing your teeth, checking your phone when you wake up, the route you take to work, the way you make tea. You don't weigh the pros and cons each time. You just do it."], ["p", "Now think of something you've tried to start — going to the gym, eating more vegetables, sleeping earlier — and how much effort each day of it required. The difference between those two lists is the difference between a habit and a decision."], ["h", "Most of life runs on habit"], ["p", "Psychologists who have asked people to record what they're doing throughout the day have found that a large share of daily behaviour is repeated in the same context almost every day — often while thinking about something else. That isn't laziness; it's efficiency. If you had to deliberately decide every action, you'd be exhausted by breakfast."]]},
  "35-discipline-without-burnout": {"chapter": "The Discipline Myth", "blocks": [["p", "The popular image of discipline: wake at 4 a.m., train twice a day, eat perfectly, never miss, never complain. Some people genuinely thrive on that. Most crash."], ["h", "What usually happens"], ["q", "The problem usually isn't a lack of discipline. It's a plan that requires a level of discipline no normal life can sustain."], ["h", "A better definition"], ["p", "Discipline is the ability to keep doing what matters, consistently, over time — including after setbacks. It's not intensity. It's continuity."], ["h", "Motivation"], ["h", "Types of motivation"], ["p", "Self-determination theory (Deci and Ryan) distinguishes:"], ["h", "The three basic needs"], ["p", "Self-determination theory suggests motivation thrives when three needs are met:"], ["li", "Autonomy: feeling that you chose this."], ["li", "Competence: feeling capable and progressing."], ["li", "Relatedness: feeling connected to others."], ["h", "Practical implications"], ["li", "Choose forms of exercise you enjoy."], ["li", "Track progress to build competence."], ["li", "Train with others or join a community."], ["li", "Connect your habits to values, not just appearance."], ["h", "Motivation follows action"], ["p", "Motivation often comes after starting, not before. Waiting to \"feel like it\" means waiting forever."]]},
  "36-body-image": {"chapter": "What Is Body Image?", "blocks": [["p", "Body image is how you see, think about, feel about and behave towards your body."], ["h", "Body image is not the same as appearance"], ["p", "Research consistently shows a weak link between how people actually look and how they feel about their bodies. Highly attractive, very fit people can have very poor body image."], ["q", "If your body image depends on your body changing, it will always be one goal away."], ["h", "How Body Image Forms"], ["h", "The Indian context"], ["p", "Many Indians grow up with frequent comments on weight (\"You've become fat!\" or \"Too thin — eat more!\"), preference for fair skin, marriage-market pressures, and Bollywood ideals. These messages can deeply shape self-worth."], ["h", "The Fitness Paradox"], ["p", "Exercise can improve body image — or worsen it."], ["h", "When fitness helps"], ["li", "Focus on what your body can do (strength, endurance, skill)."], ["li", "Enjoyment of movement."], ["li", "Community and belonging."], ["li", "Improved mood and confidence."], ["h", "When fitness harms"], ["li", "Training only to \"fix\" or punish your body."], ["li", "Constant mirror-checking, body measuring and weighing."], ["li", "Comparison with others at the gym or online."], ["li", "Rigid rules: \"I can't eat unless I've trained.\""], ["li", "Guilt or anxiety when missing sessions."]]},
  "37-emotional-eating": {"chapter": "What Is Emotional Eating?", "blocks": [["p", "Emotional eating means eating in response to emotions rather than physical hunger."], ["h", "It's normal — up to a point"], ["p", "Almost everyone eats emotionally sometimes: birthday cake, comfort food on a bad day, festival sweets. Food is tied to culture, family, celebration and comfort. That's not a problem."], ["p", "It becomes a problem when:"], ["li", "It's your main or only way to cope with emotions."], ["li", "It happens frequently."], ["li", "You feel out of control."], ["li", "It causes significant distress, guilt, or health effects."], ["q", "Emotional eating isn't a lack of willpower. It's a coping strategy that works in the short term — which is exactly why it's so hard to stop."], ["h", "Physical vs Emotional Hunger"], ["h", "The hunger scale"], ["p", "Aim to start eating around 3–4 and stop around 6–7."], ["h", "Why We Eat Emotionally"], ["h", "The reward system"], ["p", "Highly palatable foods — sugar, fat, salt combinations — activate the brain's reward system, releasing dopamine. This feels good, which reinforces the behaviour."], ["h", "Stress"], ["p", "Chronic stress raises cortisol, which may increase appetite and cravings for high-calorie foods in some people."]]},
  "38-resilient-mind": {"chapter": "What Is Resilience?", "blocks": [["p", "The American Psychological Association describes resilience as the process of adapting well in the face of adversity, trauma, tragedy, threats or significant stress."], ["h", "What resilience is"], ["li", "A process, not a fixed trait."], ["li", "Learnable — it can be developed at any age."], ["li", "Compatible with feeling pain. Resilient people still feel sad, scared and angry."], ["li", "Supported by relationships and resources, not just individual effort."], ["h", "What resilience is not"], ["li", "Never struggling."], ["li", "Hiding emotions."], ["li", "Going it alone."], ["li", "\"Toughing it out\" until you collapse."], ["q", "Resilience isn't the absence of distress. It's the ability to move through distress and keep living according to what matters."], ["h", "The surprising truth"], ["p", "Research by George Bonanno and others suggests resilience is common: after potentially traumatic events, many people show relatively stable functioning over time. Humans are often more resilient than we expect."], ["h", "Understanding Stress"], ["h", "The stress response"], ["p", "When facing a challenge, your body releases adrenaline and cortisol: heart rate rises, energy is mobilised, attention sharpens."]]},
  "39-sport-psychology": {"chapter": "What Is Sport Psychology?", "blocks": [["p", "Sport psychology is the study and application of psychological principles to sport and exercise. It aims to help athletes:"], ["li", "Perform more consistently under pressure."], ["li", "Enjoy their sport more."], ["li", "Develop as people, not just performers."], ["li", "Maintain mental health."], ["h", "Mental skills are trainable"], ["p", "Like strength or speed, mental skills improve with deliberate practice. Elite athletes typically train them as part of their preparation."], ["q", "Most athletes spend 90% of their time training the body and 10% thinking about the mind — then say that 90% of performance on the day is mental."], ["h", "The performance equation"], ["p", "Performance = Potential − Interference (adapted from Timothy Gallwey's The Inner Game of Tennis)"], ["p", "Interference includes fear, doubt, over-thinking, distraction and tension. Sport psychology works to reduce interference."], ["h", "Goal Setting"], ["h", "Types of goals"], ["p", "The best results usually come from combining all three, with most attention on process goals during competition."], ["h", "SMART goals"], ["p", "Specific, Measurable, Achievable, Relevant, Time-bound. See Vol. 42 for more."]]},
  "40-coach-psychology": {"chapter": "Why Psychology Matters", "blocks": [["h", "The retention problem"], ["p", "Many gym members stop attending within months of joining. Personal training clients often leave not because the programme was wrong, but because:"], ["li", "They didn't feel heard."], ["li", "Progress felt slow or unclear."], ["li", "Life got in the way and there was no plan B."], ["li", "The relationship didn't feel valuable."], ["h", "The coach's three roles"], ["q", "Clients come for the programme. They stay for the relationship and the results it makes possible."], ["h", "Building Rapport"], ["h", "The first session"], ["li", "Arrive prepared: read their intake form."], ["li", "Start with conversation, not exercise."], ["li", "Ask about their story: \"What brings you here now?\""], ["li", "Listen more than you talk."], ["li", "Explain the plan simply."], ["li", "End with a clear next step."], ["h", "Active listening"], ["h", "Remembering details"], ["p", "Note personal details (their children's names, their job, upcoming events) and ask about them. People stay with coaches who remember them."], ["h", "Understanding Clients"], ["h", "The stages of change (transtheoretical model)"], ["h", "Motivation profiles"], ["h", "Motivational Interviewing"], ["p", "Motivational interviewing (MI), developed by William Miller and Stephen Rollnick, is a collaborative conversation style for strengthening a person's own motivation for change. It's widely used in healthcare and increasingly in coaching."]]},
  "41-mens-mental-health": {"chapter": "The Silent Struggle", "blocks": [["h", "The numbers"], ["p", "Globally, men die by suicide at higher rates than women — in many countries, roughly two to four times higher. In India, according to National Crime Records Bureau data, men account for a large majority of reported suicides. Men are also less likely to seek mental health care."], ["h", "The \"man box\""], ["p", "Many men grow up with unwritten rules:"], ["li", "Don't cry."], ["li", "Don't show weakness."], ["li", "Solve problems yourself."], ["li", "Be the provider."], ["li", "Anger is acceptable; sadness isn't."], ["li", "Real men don't need help."], ["p", "These rules can feel protective, but they often trap men alone with their pain."], ["q", "Strength isn't never struggling. Strength is facing what's hard — including asking for help."], ["h", "The Indian context"], ["p", "Indian men often carry additional pressures:"], ["li", "Being the main earner for an extended family."], ["li", "Career and exam pressure from an early age."], ["li", "Expectations around marriage, property and status."], ["li", "Limited language or permission to discuss feelings."], ["li", "Stigma around mental illness (\"What will people say?\")."]]},
  "42-goal-setting": {"chapter": "Why Goals Fail", "blocks": [["h", "Why most resolutions fail"], ["h", "Why goals still matter"], ["p", "Goal-setting theory, developed by Edwin Locke and Gary Latham over decades of research, finds that specific, challenging goals generally lead to higher performance than vague \"do your best\" goals — when people are committed, have the ability, and get feedback."], ["q", "A goal without a plan is a wish. A plan without a system is a hope. A system with tracking and review is how results happen."], ["h", "Choosing the Right Goals"], ["h", "Start with values"], ["p", "Values are the direction; goals are the destinations along the way."], ["h", "The life areas audit"], ["p", "Rate each area from 1 to 10 for satisfaction:"], ["p", "Choose 1–3 areas to focus on for the next 90 days."], ["h", "Approach vs avoidance goals"], ["p", "Moderate evidence: Research suggests approach goals are associated with greater wellbeing and persistence than avoidance goals."], ["h", "The Anatomy of a Good Goal"], ["h", "SMART"], ["h", "From vague to SMART"], ["h", "Beyond SMART"], ["li", "Challenging: stretching but not crushing."], ["li", "Owned: your goal, not someone else's."], ["li", "Written: writing goals down may improve commitment."], ["li", "Shared: sometimes — with the right supporters."], ["h", "Outcome, Performance and Process"], ["p", "Set an outcome goal for direction, but focus daily attention on process goals — they're what you control."]]},
  "43-anabolic-steroids-the-facts": {"chapter": "Why This Book Exists", "blocks": [["p", "There is a conversation that happens in gyms all over India, usually quietly, near the dumbbell rack. A young man who has trained hard for a year or two asks someone bigger how they got that way. Often the answer is a half-truth — \"diet and discipline, bro\" — followed later, in private, by an offer: a few vials, some tablets, a \"beginner cycle\" scribbled on a piece of paper."], ["p", "Nobody in that conversation is a doctor. Nobody mentions blood pressure, fertility, or what happens to mood when the drugs stop. The products may not even contain what the label says."], ["p", "This book exists because people deserve better information than that."], ["h", "Who this book is for"], ["li", "Gym-goers who are curious, tempted, or confused by what they see online."], ["li", "People already using steroids who want to understand the risks they are taking and how to protect their health."], ["li", "Parents and partners who suspect someone they love is using and want to understand what that means."], ["li", "Coaches and gym owners who want to answer members' questions honestly."]]},
  "44-steroid-health-risks": {"chapter": "Why Monitoring Matters", "blocks": [["p", "Anabolic-androgenic steroids (AAS) affect almost every system in the body. Some effects appear quickly and visibly — acne, mood changes, fluid retention. Others develop silently: thickening heart muscle, damaged blood vessels, rising blood counts and liver changes may produce no symptoms until something serious happens."], ["h", "The illusion of safety"], ["li", "\"I feel great, so I must be fine.\""], ["li", "\"My blood work was okay last year.\""], ["li", "\"I only use moderate amounts.\""], ["li", "\"My friend has used for ten years without problems.\""], ["p", "None of these guarantees safety. Individual risk varies, products are often mislabelled or contaminated, and many harms accumulate with time and higher exposure."], ["q", "Monitoring doesn't make steroid use safe. It can detect some harms earlier — and help a person and their doctor decide when to stop."], ["h", "What this book does and doesn't do"], ["h", "The Evidence Base"], ["p", "Research on AAS health effects comes from:"], ["li", "Clinical trials using therapeutic testosterone doses (generally lower than non-medical use)."], ["li", "Observational studies of non-medical users, often recruited from gyms or clinics."], ["li", "Case reports of serious events (heart attacks, strokes, liver tumours, deaths)."], ["li", "Registry studies, such as large Scandinavian cohorts linking AAS use with health records."]]},
  "45-coming-off": {"chapter": "Deciding to Stop", "blocks": [["p", "People stop using anabolic-androgenic steroids (AAS) for many reasons:"], ["li", "Health scares — high blood pressure, heart changes, abnormal blood tests."], ["li", "Wanting to start a family."], ["li", "Side effects — acne, hair loss, gynaecomastia, mood swings."], ["li", "Cost, legal concerns, or relationship pressure."], ["li", "Feeling trapped and wanting freedom."], ["p", "Whatever your reason, deciding to stop is a significant step towards protecting your health."], ["q", "You don't have to have it all figured out. The first step is simply to decide to stop and get support."], ["h", "Why stopping can be hard"], ["li", "Physical withdrawal: low energy, low libido, low mood."], ["li", "Loss of size and strength."], ["li", "Identity and body image tied to the \"enhanced\" physique."], ["li", "Social circles where use is normal."], ["li", "Dependence — a recognised pattern in some long-term users."], ["h", "What Happens When You Stop"], ["h", "The HPG axis"], ["p", "During AAS use, the brain senses high androgen levels and reduces signals (LH and FSH) to the testes. The testes produce little testosterone and fewer sperm."], ["p", "When external androgens are stopped:"], ["li", "Androgen levels fall."], ["li", "The brain slowly restarts signalling."], ["li", "The testes gradually resume production."], ["p", "During this gap, many people experience low testosterone (hypogonadism)."]]},
  "46-natural-vs-enhanced": {"chapter": "The Comparison Trap", "blocks": [["p", "Every day, millions of people compare their bodies with images online — and feel inadequate."], ["h", "What's often hidden"], ["q", "You're comparing your everyday reality with someone else's carefully constructed peak."], ["h", "What Natural Training Can Achieve"], ["h", "How much muscle can you gain naturally?"], ["p", "Estimates from coaches and researchers vary, but a commonly cited approximate guide for men with good training and nutrition is:"], ["p", "Women typically gain roughly half these amounts in absolute terms, though relative gains can be similar."], ["p", "Limited evidence: These are rough heuristics, not precise science — individuals vary widely because of genetics, age, starting point, programme quality and consistency."], ["h", "Rate slows over time"], ["p", "Progress is fastest at the beginning and slows as you approach your genetic potential. That's normal, not failure."], ["h", "Natural limits"], ["p", "Researchers have proposed indices like the fat-free mass index (FFMI) to estimate natural muscularity. One frequently cited study (Kouri et al., 1995) found that men who didn't use steroids rarely exceeded an FFMI of about 25. This isn't a hard rule — exceptional genetics exist — but very high values combined with very low body fat and rapid gains warrant scepticism."]]},
  "47-peptides-explained": {"chapter": "What Are Peptides?", "blocks": [["p", "Peptides are short chains of amino acids — the same building blocks that make up proteins. There's no strict cut-off, but chains of roughly 2–50 amino acids are usually called peptides, while longer chains are called proteins."], ["h", "Peptides in your body"], ["p", "Your body makes thousands of peptides that act as:"], ["li", "Hormones: insulin, glucagon, oxytocin, vasopressin, GLP-1."], ["li", "Neurotransmitters and neuromodulators: endorphins, substance P."], ["li", "Antimicrobial defences: defensins."], ["li", "Signalling molecules for growth, repair and appetite."], ["h", "Peptides in food"], ["p", "Dietary proteins are broken down into peptides and amino acids during digestion. Some food-derived peptides (in milk, for instance) are studied for biological effects, but most are digested before reaching the bloodstream in significant amounts."], ["q", "\"Peptide\" describes a type of molecule, not a quality. Insulin is a peptide. So are snake venoms. Being a peptide doesn't make something safe, natural or effective."], ["h", "How Peptide Medicines Work"], ["h", "Receptors"], ["p", "Most peptide hormones act by binding to specific receptors on cells, triggering a cascade of effects — like a key fitting a lock."]]},
  "48-glp1-weight-loss": {"chapter": "What Are GLP-1 Medicines?", "blocks": [["p", "GLP-1 (glucagon-like peptide-1) is a hormone released by your gut after eating. It helps regulate blood sugar and appetite."], ["p", "GLP-1 receptor agonists are medicines that mimic GLP-1 but last much longer in the body. Newer medicines also act on other hormone receptors."], ["p", "Brand names, approved uses and availability vary by country and change over time. In India, several of these medicines are available by prescription, and new versions — including generics as patents expire — are expected to change prices and access."], ["q", "These are powerful, effective medicines. They're also prescription drugs with real side effects. Both things are true."], ["h", "How They Work"], ["h", "Main effects"], ["h", "\"Food noise\""], ["p", "Many patients describe a reduction in constant thoughts about food. Research is exploring how these medicines affect brain reward pathways."], ["h", "Weight loss comes from eating less"], ["p", "GLP-1 medicines don't \"melt fat\" directly. They help people eat less by reducing appetite — so a calorie deficit still drives weight loss."]]},
  "49-research-chemicals": {"chapter": "The Grey Market", "blocks": [["h", "\"For research purposes only\""], ["p", "Many products are sold with labels like \"for research purposes only\" or \"not for human consumption\". This labelling is often a legal manoeuvre — the products are clearly marketed to people who'll consume them."], ["h", "Where they're sold"], ["li", "Websites and online marketplaces."], ["li", "Social media and messaging apps."], ["li", "Gym contacts and \"coaches\"."], ["li", "Supplement shops (sometimes hidden in \"natural\" products)."], ["h", "Why people buy them"], ["li", "Belief that they're \"safer than steroids\"."], ["li", "Perceived legality."], ["li", "Easy online access."], ["li", "Influencer endorsements."], ["li", "Desire for fast results."], ["q", "\"Legal to sell as a research chemical\" doesn't mean \"safe to consume\", \"approved\", or even \"what the label says\"."], ["h", "What's Actually in the Bottle?"], ["p", "Independent analyses of products sold online as SARMs and other research chemicals have found:"], ["li", "Some contain no active ingredient."], ["li", "Some contain a different substance from the one labelled."], ["li", "Many contain different amounts from the label."], ["li", "Some contain unlisted substances, including other SARMs, steroids or stimulants."], ["p", "A widely cited 2017 study published in JAMA found that only about half of products sold online as SARMs contained the labelled substance, and many contained unlisted substances."]]},
  "50-hormones-ageing": {"chapter": "How Hormones Change with Age", "blocks": [["h", "Normal ageing vs disease"], ["p", "Some hormonal decline is a normal part of ageing. The key medical question is whether a person has a condition that needs treatment — not whether their levels match those of a 25-year-old."], ["q", "\"Optimising\" hormones to youthful levels isn't the same as treating a disease — and doesn't have the same evidence base."], ["h", "Low Testosterone in Men"], ["h", "Male hypogonadism"], ["p", "A clinical condition in which the body doesn't produce enough testosterone, diagnosed through:"], ["li", "Symptoms consistent with low testosterone (see below)."], ["li", "Repeatedly low blood levels, usually measured in the morning on at least two occasions."], ["li", "Investigation of the cause (e.g. pituitary problems, testicular problems, medications, obesity)."], ["h", "Possible symptoms"], ["p", "Many of the less specific symptoms have other common causes: poor sleep, depression, obesity, diabetes, alcohol, stress and other illnesses."], ["h", "Lifestyle factors that lower testosterone"], ["li", "Obesity (especially abdominal fat)."], ["li", "Poor sleep and sleep apnoea."], ["li", "Heavy alcohol use."], ["li", "Chronic stress."], ["li", "Some medicines (e.g. opioids, glucocorticoids)."], ["li", "Past anabolic steroid use (Vol. 45)."], ["p", "Moderate evidence: Weight loss, better sleep and reduced alcohol can raise testosterone in some men with low-normal levels."]]},
  "51-the-kettlebell-way": {"chapter": "Why Kettlebells?", "blocks": [["p", "Kettlebells have been used for centuries — Russian market traders famously used them as counterweights and then as competition weights. Today they're used by athletes, military units, physiotherapists and everyday gym-goers."], ["h", "What makes them different"], ["p", "A dumbbell's weight sits in your hand. A kettlebell's centre of mass sits below and away from the handle. That offset changes everything:"], ["li", "Swinging movements become possible and safe, teaching powerful hip extension."], ["li", "Grip and forearms work harder, especially in ballistic lifts."], ["li", "The rack position lets you hold the bell on your forearm for presses, squats and carries."], ["li", "Transitions between exercises are fast, so strength and conditioning blend together."], ["h", "What kettlebells develop"], ["p", "Moderate evidence: Research shows kettlebell training can improve strength, power and aerobic fitness, with effects broadly similar to other resistance and interval training — it's not magic, but it's very efficient."], ["q", "The kettlebell doesn't replace a barbell for maximal strength. It complements one — and for many people training at home, it's the single best investment."]]},
  "52-couch-to-10k": {"chapter": "Why Run?", "blocks": [["p", "Running needs almost nothing: shoes, a safe route and a plan. It's one of the most accessible ways to build fitness."], ["h", "What regular running can do"], ["h", "Why beginners quit"], ["li", "Starting too fast and too much."], ["li", "Running every run hard and out of breath."], ["li", "Ignoring early niggles until they become injuries."], ["li", "Unrealistic expectations of speed."], ["li", "Running alone without structure or goals."], ["q", "The secret of beginner running is to run slower than you think you should — slow enough to talk."], ["h", "Before You Start"], ["h", "See a doctor first if you"], ["li", "Have heart disease, chest pain, or a family history of sudden cardiac death at a young age."], ["li", "Have high blood pressure, diabetes, or are very overweight and new to exercise."], ["li", "Feel dizzy, faint or unusually breathless with mild exertion."], ["li", "Are pregnant or recently postnatal."], ["li", "Have joint problems or recent injuries."], ["q", "Stop and seek urgent medical help (112) if you experience chest pain or pressure, fainting, severe breathlessness or a racing, irregular heartbeat while running."]]},
  "53-exercise-for-type-2-diabetes": {"chapter": "Diabetes in India", "blocks": [["p", "Type 2 diabetes develops when the body becomes less responsive to insulin (insulin resistance) and the pancreas can't keep up with the demand. Blood sugar rises, and over years high glucose can damage blood vessels, nerves, eyes, kidneys and the heart."], ["h", "Why Indians are at higher risk"], ["li", "Genetics and body composition: South Asians tend to carry more fat around the abdomen and organs and less muscle at the same body weight — a pattern linked to insulin resistance."], ["li", "Lower BMI thresholds: diabetes risk rises at lower BMIs in South Asians. Many Indian guidelines use 23 as the cut-off for overweight."], ["li", "Diet: large portions of refined carbohydrates (white rice, maida, sugar) with lower protein and fibre."], ["li", "Inactivity: desk jobs, long commutes and limited safe spaces for activity."], ["li", "Earlier onset: diabetes often appears in the 30s and 40s, a decade earlier than in many Western populations."], ["h", "The numbers that matter"], ["p", "These are common diagnostic thresholds; your doctor will interpret your results and set your personal targets."], ["q", "Prediabetes is not \"almost nothing\". It's an opportunity: lifestyle changes at this stage can delay or prevent diabetes for many people."]]},
  "54-pcos-train-eat-thrive": {"chapter": "Understanding PCOS", "blocks": [["p", "Polycystic ovary syndrome (PCOS) is one of the most common hormonal conditions in women of reproductive age. Estimates vary by definition and population, but studies in India suggest roughly 1 in 10 women — or more — may be affected."], ["h", "Despite the name"], ["p", "PCOS isn't primarily a disease of \"cysts\". The \"cysts\" seen on ultrasound are usually small follicles — eggs that haven't matured and been released. Many women with PCOS don't have polycystic-looking ovaries, and some women without PCOS do."], ["h", "How it's diagnosed"], ["p", "Doctors commonly use the Rotterdam criteria: at least two of these three, after ruling out other causes (such as thyroid disease or high prolactin):"], ["p", "In adolescents, diagnosis is more cautious, since irregular cycles and acne are common in the first years after periods start."], ["h", "Why it matters long term"], ["p", "PCOS is linked with higher risk of:"], ["li", "Insulin resistance, prediabetes and type 2 diabetes."], ["li", "Gestational diabetes in pregnancy."], ["li", "Abnormal cholesterol and, potentially, heart disease."], ["li", "Endometrial (womb lining) thickening and cancer, if periods are very infrequent."], ["li", "Sleep apnoea."], ["li", "Anxiety, depression and body-image concerns."], ["q", "PCOS is a lifelong metabolic and hormonal condition, not just a fertility issue. Lifestyle changes help at every stage — not only when you want to conceive."]]},
  "55-healthy-heart-plan": {"chapter": "The Heart Problem in India", "blocks": [["p", "Cardiovascular disease — heart attacks, strokes and related conditions — is one of the leading causes of death in India. South Asians often develop heart disease 5–10 years earlier than many other populations."], ["h", "Why the risk is higher"], ["h", "The good news"], ["p", "Much of the risk is modifiable. Lifestyle changes combined with appropriate medicines substantially reduce the risk of heart attack and stroke."], ["q", "The most dangerous heart risk factors are the silent ones. You can't feel high blood pressure or high cholesterol — you have to measure them."], ["h", "Blood Pressure Explained"], ["p", "Blood pressure is the force of blood against your artery walls, written as two numbers:"], ["li", "Systolic (top number): pressure when the heart beats."], ["li", "Diastolic (bottom number): pressure between beats."], ["h", "Categories (commonly used guide)"], ["p", "Different guidelines use slightly different thresholds (some define hypertension from 140/90). Your doctor will set your target."], ["h", "Why it matters"], ["p", "High blood pressure damages arteries over time, increasing the risk of heart attack, stroke, heart failure, kidney disease and dementia."]]},
  "56-fit-kids-strong-teens": {"chapter": "Why Activity Matters", "blocks": [["p", "Physical activity in childhood shapes health for life."], ["h", "The Indian reality"], ["li", "Long school hours, tuition and coaching classes leave little time."], ["li", "Limited safe play spaces in cities."], ["li", "Academic pressure often pushes sport aside."], ["li", "Screen time has risen sharply."], ["q", "Active children often learn better, not worse. Movement is an investment in academic performance, not a distraction from it."], ["h", "How Much Is Enough?"], ["p", "These recommendations are adapted from WHO guidelines."], ["h", "What counts as moderate and vigorous?"], ["h", "Bone- and muscle-strengthening"], ["h", "Play First"], ["p", "For young children, play is exercise. Unstructured play builds coordination, creativity and joy in movement."], ["h", "Fundamental movement skills"], ["p", "These are the \"ABCs\" of movement that underpin all sports:"], ["p", "Children who master these skills early are more likely to stay active as teenagers."], ["h", "Ideas for play at home and nearby"], ["q", "Traditional Indian games like kho-kho, lagori and gilli-danda are excellent for speed, agility and teamwork — and need almost no equipment."], ["h", "Sport Without Stress"], ["h", "Why children quit sport"], ["p", "Research consistently shows the top reason children drop out of sport is that it stops being fun. Other reasons include:"], ["li", "Too much pressure to win."], ["li", "Harsh coaching or criticism."], ["li", "Lack of playing time."], ["li", "Early specialisation and burnout."], ["li", "Feeling not good enough."]]},
  "57-functional-fitness": {"chapter": "What Is Functional Fitness?", "blocks": [["p", "\"Functional\" fitness simply means training that improves your ability to do the physical tasks of your life."], ["h", "The idea"], ["p", "Every daily task is built from a few basic movement patterns:"], ["h", "What functional fitness is not"], ["li", "It's not standing on wobble boards while juggling."], ["li", "It's not only bodyweight training."], ["li", "It's not a replacement for strength — strong muscles are the foundation of function."], ["q", "The most functional thing you can be is strong. Function is strength, expressed through good movement."], ["h", "Why It Matters"], ["h", "Benefits"], ["li", "Fewer aches from daily tasks."], ["li", "Lower risk of strains when lifting and carrying."], ["li", "Better balance and lower fall risk."], ["li", "Easier stairs, travel and play."], ["li", "More independence with age."], ["h", "The ageing curve"], ["p", "Without training, adults lose muscle mass and strength gradually from around their 30s, accelerating after 60. Power — the ability to move quickly — declines even faster. Training can slow, stop or partially reverse these changes at any age (Vol. 7, Vol. 60)."]]},
  "58-gut-health": {"chapter": "The Gut, Explained", "blocks": [["p", "Your digestive tract runs from mouth to anus — roughly 9 metres of specialised tubing that breaks down food, absorbs nutrients and water, protects you from harmful organisms, and removes waste."], ["h", "The gut–brain connection"], ["p", "The gut has its own extensive network of nerves and communicates constantly with the brain through nerves, hormones and immune signals. This helps explain why stress can cause \"butterflies\", diarrhoea or constipation — and why gut problems can affect mood."], ["h", "The Microbiome"], ["p", "Your large intestine is home to trillions of bacteria, along with other microbes. Together they're called the gut microbiome."], ["h", "What gut microbes do"], ["li", "Ferment dietary fibre into short-chain fatty acids, which nourish the cells lining the colon and may have wider benefits."], ["li", "Help train and regulate the immune system."], ["li", "Produce some vitamins (such as vitamin K and some B vitamins)."], ["li", "Compete with harmful organisms."], ["h", "What we know — and don't"], ["q", "Most of what helps your microbiome is boringly simple: eat more fibre and more types of plant foods, move regularly, sleep well, and avoid unnecessary antibiotics."]]},
  "59-ayurveda-meets-evidence": {"chapter": "Two Ways of Knowing", "blocks": [["h", "Ayurveda"], ["p", "Ayurveda (\"knowledge of life\") is one of the world's oldest systems of medicine, with roots in classical texts such as the Charaka Samhita and Sushruta Samhita. It emphasises balance, prevention, daily routines, food as medicine, and individualised care. In India, Ayurveda is recognised within the AYUSH system and practised by trained practitioners (BAMS graduates)."], ["h", "Modern evidence-based medicine"], ["p", "Modern medicine tests treatments using controlled studies, measuring outcomes and comparing them with placebos or standard care, and it changes its recommendations as evidence accumulates."], ["h", "How this book approaches them"], ["li", "Respect: Ayurvedic practices are part of India's cultural heritage, and many embody sensible, time-tested wisdom."], ["li", "Honesty: traditional use isn't the same as proof of effectiveness or safety. Some claims are well supported; many are unproven; some products carry risks."], ["li", "Integration: the most helpful approach for most people combines healthy traditional habits with modern medical care."], ["q", "Old isn't automatically right, and new isn't automatically better. Evidence is the bridge between them."]]},
  "60-strong-at-sixty": {"chapter": "It's Never Too Late", "blocks": [["p", "Many older adults believe it's \"too late\" to start exercising, or that exercise is risky. The evidence says the opposite: older adults can gain substantial strength, balance and mobility — even in their 80s and 90s."], ["p", "Moderate evidence: Classic studies have shown that frail adults in their 80s and 90s doubled or nearly tripled their leg strength after a few months of supervised resistance training."], ["h", "What changes with age"], ["h", "Use it or lose it"], ["p", "Much age-related decline is due to inactivity, not age alone. Regular exercise slows or partially reverses many of these changes."], ["q", "The goal isn't to look like you did at 25. It's to get up from a chair easily, climb stairs, carry your shopping, play with your grandchildren, and live independently for as long as possible."], ["h", "The Benefits"], ["h", "Before You Begin"], ["h", "See your doctor first if you"], ["li", "Have heart disease, chest pain, or recent heart problems."], ["li", "Have uncontrolled high blood pressure."], ["li", "Have had recent falls, dizziness or fainting."], ["li", "Have osteoporosis with previous fractures."], ["li", "Have had recent surgery or joint replacement."], ["li", "Have diabetes with complications."], ["li", "Take medicines that cause dizziness."], ["li", "Are starting exercise after a long period of inactivity."]]},
};
